import React from 'react';
import { useAuth } from '../AuthContext';

function Login() {
  const { demoUsers, loading, login } = useAuth();

  if (loading) {
    return (
      <div className="feed-empty" style={{ height: '100vh' }}>
        <div className="spinner" />
        <div style={{ marginTop: '20px' }}>Loading environment...</div>
      </div>
    );
  }

  return (
    <div className="feed-empty" style={{ height: '100vh' }}>
      <div className="header-logo" style={{ marginBottom: '30px', transform: 'scale(1.5)', flexDirection: 'column', alignItems: 'center', textAlign: 'center' }}>
        <div className="header-logo-icon">⚡</div>
        <div className="header-logo-text" style={{ fontSize: '18px', marginTop: '10px' }}>Cyber Situational Awareness<br/><span>Multi-Tenant Platform</span></div>
      </div>

      <div className="feed-empty-title" style={{ marginBottom: '10px' }}>
        Select your role to continue
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '15px', width: '300px' }}>
        {demoUsers.map(user => (
          <button
            key={user.id}
            className="submit-btn"
            onClick={() => login(user)}
          >
            Log in as {user.name} 
            <br/>
            <span style={{ fontSize: '9px', opacity: 0.7, fontWeight: 'normal' }}>
              ({user.organization.name})
            </span>
          </button>
        ))}
      </div>
    </div>
  );
}

export default Login;
